#ifndef CONTADOR_H
#define CONTADOR_H

typedef struct {
  int valor;
} TContador;

void inicializar(TContador *c);
void contar(TContador *c);
int obtener(TContador c);

#endif

#include <stdio.h>
#include "contador.h"

int main() {
  TContador c;

  inicializar(&c);
  contar(&c);
  contar(&c);
  c.valor = c.valor + 10;
  printf("%d", obtener(c));
  return 0;
}

